92	function detectTailnetBindHost(): string | undefined {
93	  const explicit = process.env.PAPERCLIP_TAILNET_BIND_HOST?.trim();
94	  if (explicit) return explicit;
95	
96	  try {
97	    const stdout = execFileSync("tailscale", ["ip", "-4"], {
98	      encoding: "utf8",
99	      stdio: ["ignore", "pipe", "ignore"],
100	      timeout: TAILSCALE_DETECT_TIMEOUT_MS,
101	    });
102	    return stdout
103	      .split(/\r?\n/)
104	      .map((line) => line.trim())
105	      .find(Boolean);
106	  } catch {
107	    return undefined;
108	  }
109	}
